def md5(yol):
    return hashlib.md5(open(yol, "rb").read()).hexdigest() if os.path.exists(yol) else ""

if not os.path.isfile("kutuphane/kaynak.py"):
    sys.exit("HATA: kod klasöründe değilsin (cd /DATA/AppData/dedplay-studyo/kod/studyo)")
yazilacak = []
for yol, eski, yeni, veri in DOSYALAR:
    simdi = md5(yol)
    if simdi == yeni:
        print("ATLANDI (zaten 0.5.41):", yol)
    elif simdi == eski:
        yazilacak.append((yol, yeni, veri))
    else:
        sys.exit("HATA: " + yol + " beklenen 0.5.40 dosyası değil (md5 " + (simdi or "yok") + "); hiçbir dosya değiştirilmedi")
for yol, yeni, veri in yazilacak:
    icerik = zlib.decompress(base64.b85decode("".join(veri.split())))
    if hashlib.md5(icerik).hexdigest() != yeni:
        sys.exit("HATA: yama içi bozuk: " + yol)
    with open(yol, "wb") as f:
        f.write(icerik)
    print("YAZILDI:", yol)
print("TAMAM: 0.5.41")
